type Row = Record<string, any>;

/** Minimal PostgREST-shaped query builder over in-memory tables (only what the code paths use). */
export function fakeSupabase(tables: Record<string, Row[]>, rpcs: Record<string, (args: any) => unknown> = {}) {
  const log: string[] = [];
  function from(table: string) {
    tables[table] ??= [];
    const filters: ((r: Row) => boolean)[] = [];
    let op: "select" | "delete" | "upsert" = "select";
    let upsertRows: Row[] = [];
    let upsertConflict: string[] = [];
    let rangeFrom = 0;
    let rangeTo = Infinity;
    let single = false;

    const run = () => {
      const rows = tables[table];
      if (op === "upsert") {
        for (const r of upsertRows) {
          const dup = rows.some((x) => upsertConflict.every((k) => x[k] === r[k]));
          if (!dup) rows.push({ added_at: new Date().toISOString(), ...r });
        }
        log.push(`upsert ${table}`);
        return { data: null, error: null };
      }
      if (op === "delete") {
        tables[table] = rows.filter((r) => !filters.every((f) => f(r)));
        log.push(`delete ${table}`);
        return { data: null, error: null };
      }
      log.push(`select ${table}`);
      const out = rows.filter((r) => filters.every((f) => f(r))).slice(rangeFrom, rangeTo + 1);
      if (single) return { data: out[0] ?? null, error: null };
      return { data: out, error: null };
    };

    const b: any = {
      select: () => b,
      eq: (c: string, v: unknown) => (filters.push((r) => r[c] === v), b),
      in: (c: string, vs: unknown[]) => (filters.push((r) => vs.includes(r[c])), b),
      order: () => b,
      limit: (n: number) => ((rangeTo = n - 1), b),
      range: (a: number, z: number) => ((rangeFrom = a), (rangeTo = z), b),
      maybeSingle: () => ((single = true), Promise.resolve(run())),
      delete: () => ((op = "delete"), b),
      upsert: (row: Row | Row[], opts?: { onConflict?: string }) => {
        op = "upsert";
        upsertRows = Array.isArray(row) ? row : [row];
        upsertConflict = (opts?.onConflict ?? "id").split(",");
        return b;
      },
      then: (res: (v: unknown) => unknown, rej?: (e: unknown) => unknown) => Promise.resolve(run()).then(res, rej),
    };
    return b;
  }
  return {
    log,
    tables,
    client: {
      from,
      rpc: async (name: string, args: unknown) => {
        log.push(`rpc ${name}`);
        const fn = rpcs[name];
        if (!fn) return { data: null, error: { message: `no rpc ${name}` } };
        return { data: fn(args), error: null };
      },
    },
  };
}

/** The world the reserve-flow integration test runs in. */
export function readerWorld() {
  const tables: Record<string, Row[]> = {
    briefings: briefingRows(),
    faraday_themes: [],
    faraday_domains: [],
    faraday_subdomains: [],
    companies: [
      { company_uid: "C1", canonical_name: "Wolfspeed" },
      { company_uid: "C2", canonical_name: "Nutanix" },
    ],
    // Cache ids are briefings.id for native rows; library_checkout joins on status = 'Available'.
    library_catalog_cache: [
      { id: PUBLISHED_ID, status: "Available", briefing_type: "company", briefing_description: "A short abstract." },
      { id: PLANNED_ID, status: "Coming Soon", briefing_type: "company" },
    ],
    subscribers: [{ id: SUB, email: EMAIL }],
    library_cart_items: [],
    library_entitlements: [],
  };
  // Mirrors library_checkout (migration 20260620064621) closely enough for the flow: Available,
  // not-yet-owned cart lines become entitlements and leave the cart, once per token.
  const processed = new Map<string, unknown>();
  const rpcs = {
    library_checkout: ({ p_sub, p_idempotency_token }: { p_sub: string; p_idempotency_token: string }) => {
      if (processed.has(p_idempotency_token)) return { ...(processed.get(p_idempotency_token) as object), replayed: true };
      const available = new Set(tables.library_catalog_cache.filter((c) => c.status === "Available").map((c) => c.id));
      const owned = new Set(tables.library_entitlements.filter((e) => e.subscriber_id === p_sub).map((e) => e.briefing_id));
      const lines = tables.library_cart_items
        .filter((c) => c.subscriber_id === p_sub && available.has(c.briefing_id) && !owned.has(c.briefing_id))
        .map((c) => c.briefing_id as string);
      if (!lines.length) return { error: "empty_cart" };
      for (const id of lines) tables.library_entitlements.push({ subscriber_id: p_sub, briefing_id: id, source: "checkout" });
      tables.library_cart_items = tables.library_cart_items.filter((c) => !(c.subscriber_id === p_sub && lines.includes(c.briefing_id)));
      const result = { ok: true, charged: lines.length * 10, owned: lines, meter: 10 };
      processed.set(p_idempotency_token, result);
      return result;
    },
  };
  return fakeSupabase(tables, rpcs);
}
